package com.procats.study;
import com.getcapacitor.*;import com.getcapacitor.annotation.CapacitorPlugin;import android.content.*;import android.net.Uri;import android.util.AtomicFile;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
@CapacitorPlugin(name="ProcatsDevice")
public class ProcatsDevicePlugin extends Plugin {
 private AtomicFile file(PluginCall call)throws Exception{String uid=call.getString("account");if(uid==null||uid.isEmpty()||uid.length()>200)throw new Exception("Invalid account");StringBuilder name=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(uid.getBytes(StandardCharsets.UTF_8)))name.append(String.format("%02x",b));File dir=new File(getContext().getNoBackupFilesDir(),"workspaces");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Storage unavailable");return new AtomicFile(new File(dir,name+".json"));}
 @PluginMethod public synchronized void readJournal(PluginCall call){try{JSObject out=new JSObject();try{out.put("value",new String(file(call).readFully(),StandardCharsets.UTF_8));}catch(FileNotFoundException e){out.put("value",(String)null);}call.resolve(out);}catch(Exception e){call.reject("Cannot read device records",e);}}
 @PluginMethod public synchronized void writeJournal(PluginCall call){AtomicFile target=null;FileOutputStream output=null;try{String value=call.getString("value");if(value==null||value.length()>32000000)throw new IOException("Invalid journal");new org.json.JSONObject(value);target=file(call);output=target.startWrite();output.write(value.getBytes(StandardCharsets.UTF_8));target.finishWrite(output);call.resolve();}catch(Exception e){if(target!=null&&output!=null)target.failWrite(output);call.reject("Cannot save device records",e);}}
 @PluginMethod public synchronized void removeJournal(PluginCall call){try{file(call).delete();call.resolve();}catch(Exception e){call.reject("Cannot clear device records",e);}}
 @PluginMethod public void openLink(PluginCall call){try{Uri uri=Uri.parse(call.getString("url",""));if(!"https".equals(uri.getScheme()))throw new Exception("Unsupported link");getActivity().startActivity(new Intent(Intent.ACTION_VIEW,uri));call.resolve();}catch(Exception e){call.reject("Cannot open resource",e);}}
}
